package com.mreedon.burnlog;

import java.util.HashMap;
import java.util.Map;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.GameState;
import net.runelite.api.Skill;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.StatChanged;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.PluginMessage;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;

/**
 * Emits one event per Firemaking XP drop, over RuneLite's plugin-message bus to Dink.
 *
 * <p>Why an XP drop and not a chat message: burning logs on a forester's campfire prints
 * nothing per log. The only chat line is "You finish adding the &lt;type&gt; to the fire",
 * one per inventory, and it does not say how many logs the batch held -- so anything built
 * on it has to multiply by an assumed inventory size. An XP drop carries the exact number
 * the game awarded, which needs no per-log XP table, no outfit-bonus modelling, and no
 * calibration against a later hiscores reading.
 *
 * <p>Nothing here touches the network. Dink owns the webhook; this only posts an event that
 * Dink acts on if the user has enabled External Plugin Notifications. The {@code metadata}
 * map is Dink's escape hatch for non-Discord consumers -- it is serialised into the webhook
 * body untouched, so a local handler gets the raw numbers rather than a sentence.
 *
 * @see <a href="https://github.com/pajlads/DinkPlugin/blob/master/docs/external-plugin-messaging.md">Dink external-plugin messaging</a>
 */
@Slf4j
@PluginDescriptor(
	name = "Burn Log",
	description = "Records every Firemaking XP drop through Dink, one event per log burned.",
	tags = {"firemaking", "burn", "campfire", "logs", "xp", "dink", "tracker"}
)
public class BurnLogPlugin extends Plugin
{
	private static final String NAMESPACE = "dink";
	private static final String NAME = "notify";
	private static final String SOURCE = "Burn Log";

	@Inject
	private EventBus eventBus;

	/**
	 * Last Firemaking XP total seen, or -1 for "no baseline yet".
	 *
	 * <p>The first StatChanged after a login carries the account's TOTAL Firemaking XP
	 * rather than a drop, so it seeds this and emits nothing. Without the guard every
	 * login would report a single burn worth the player's entire Firemaking XP.
	 */
	private int lastXp = -1;

	@Override
	protected void startUp()
	{
		lastXp = -1;
	}

	@Override
	protected void shutDown()
	{
		lastXp = -1;
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		GameState state = event.getGameState();
		// Drop the baseline whenever the account behind it might change. Hopping keeps the
		// same account but re-fires StatChanged; a login screen can be followed by a
		// DIFFERENT account, and a stale baseline would turn that into one enormous
		// fictional burn. Re-seeding costs a single skipped drop, which is the cheap error.
		if (state == GameState.LOGIN_SCREEN || state == GameState.HOPPING
			|| state == GameState.CONNECTION_LOST)
		{
			lastXp = -1;
		}
	}

	@Subscribe
	public void onStatChanged(StatChanged event)
	{
		if (event.getSkill() != Skill.FIREMAKING)
		{
			return;
		}

		int xp = event.getXp();
		if (lastXp < 0)
		{
			lastXp = xp;
			return;
		}

		int delta = xp - lastXp;
		lastXp = xp;

		// StatChanged also fires when only the BOOSTED level moves, which leaves XP
		// untouched. That is not a burn, and neither is anything negative.
		if (delta <= 0)
		{
			return;
		}

		emit(delta, xp, event.getLevel());
	}

	private void emit(int delta, int total, int level)
	{
		Map<String, Object> metadata = new HashMap<>();
		metadata.put("event", "xp");
		// name() rather than a display string: the consumer normalises casing, and an
		// enum name cannot drift the way a label can.
		metadata.put("skill", Skill.FIREMAKING.name());
		metadata.put("xp", delta);
		metadata.put("total", total);
		metadata.put("level", level);
		metadata.put("at", System.currentTimeMillis());

		Map<String, Object> data = new HashMap<>();
		data.put("sourcePlugin", SOURCE);
		data.put("title", "Burn Log");
		data.put("text", "%USERNAME% gained " + delta + " Firemaking xp");
		data.put("imageRequested", false);
		data.put("metadata", metadata);

		// debug, not info: this fires up to ~975 times an hour at a campfire.
		log.debug("burn: +{} xp (total {}, level {})", delta, total, level);
		eventBus.post(new PluginMessage(NAMESPACE, NAME, data));
	}
}
